<?php
require_once __DIR__.'/../includes/auth.php';requireHOD();$p=db();$d=$_SESSION['user']['department_id'];$f=['batch'=>(int)($_GET['batch']??0),'semester'=>(int)($_GET['semester']??0),'subject'=>(int)($_GET['subject']??0),'lecturer'=>(int)($_GET['lecturer']??0),'type'=>$_GET['type']??''];$bq=$p->prepare('SELECT * FROM batches WHERE department_id=? ORDER BY batch_name');$bq->execute([$d]);$batches=$bq->fetchAll();$semesters=$p->query('SELECT * FROM semesters ORDER BY semester_number')->fetchAll();$q=$p->prepare('SELECT * FROM subjects WHERE department_id=? ORDER BY subject_code');$q->execute([$d]);$subjects=$q->fetchAll();$q=$p->prepare("SELECT * FROM users WHERE department_id=? AND role='lecturer' ORDER BY name");$q->execute([$d]);$lecturers=$q->fetchAll();$sessions=[];$students=[];$records=[];
if($f['batch']){$sql='SELECT a.id,a.attendance_date,a.lecture_number,a.session_type,s.subject_code FROM attendance_sessions a JOIN batch_subjects bs ON bs.id=a.batch_subject_id JOIN subjects s ON s.id=bs.subject_id WHERE bs.batch_id=?';$args=[$f['batch']];foreach(['semester'=>'bs.semester_id','subject'=>'s.id','lecturer'=>'bs.lecturer_id'] as $key=>$column)if($f[$key]){$sql.=" AND $column=?";$args[]=$f[$key];}if(in_array($f['type'],['lecture','practical'],true)){$sql.=' AND a.session_type=?';$args[]=$f['type'];}$sql.=' ORDER BY a.attendance_date,a.lecture_number';$q=$p->prepare($sql);$q->execute($args);$sessions=$q->fetchAll();$q=$p->prepare("SELECT * FROM students WHERE batch_id=? AND status='active' ORDER BY registration_number");$q->execute([$f['batch']]);$students=$q->fetchAll();if($sessions){$marks=implode(',',array_fill(0,count($sessions),'?'));$q=$p->prepare("SELECT attendance_session_id,student_id,status FROM attendance_records WHERE attendance_session_id IN ($marks)");$q->execute(array_column($sessions,'id'));foreach($q as $r)$records[$r['student_id']][$r['attendance_session_id']]=$r['status'];}}
$title='Attendance Sheet';require __DIR__.'/../includes/header.php';?>
<section class="panel"><h2>Attendance Sheet Filters</h2><form method="get" class="inline-form"><label>Batch<select name="batch" required><option value="">Select batch</option><?php foreach($batches as $x):?><option value="<?=$x['id']?>" <?=$f['batch']==$x['id']?'selected':''?>><?=e($x['batch_name'])?></option><?php endforeach?></select></label><label>Semester<select name="semester"><option value="">All semesters</option><?php foreach($semesters as $x):?><option value="<?=$x['id']?>" <?=$f['semester']==$x['id']?'selected':''?>><?=e($x['semester_name'])?></option><?php endforeach?></select></label><label>Subject<select name="subject"><option value="">All subjects</option><?php foreach($subjects as $x):?><option value="<?=$x['id']?>" <?=$f['subject']==$x['id']?'selected':''?>><?=e($x['subject_code'])?></option><?php endforeach?></select></label><label>Lecturer<select name="lecturer"><option value="">All lecturers</option><?php foreach($lecturers as $x):?><option value="<?=$x['id']?>" <?=$f['lecturer']==$x['id']?'selected':''?>><?=e($x['name'])?></option><?php endforeach?></select></label><label>Type<select name="type"><option value="">All types</option><option value="lecture">Lecture</option><option value="practical">Practical</option></select></label><button>Show Sheet</button></form></section>
<?php if($f['batch']):?><section class="panel attendance-record-panel"><?php if(!$sessions):?><p>No attendance sessions match the selected filters.</p><?php else:?><div class="attendance-legend" aria-label="Attendance status key"><span class="present-key">P: Present</span><span class="medical-key">M: Medical</span><span class="absent-key">A: Absent</span><span class="pending-key">Not recorded</span></div><p class="table-scroll-hint">Swipe the table sideways to view dates</p><div class="table-wrap attendance-matrix-wrap" tabindex="0" role="region" aria-label="Attendance records. Scroll horizontally to view all dates."><table class="attendance-matrix"><tr><th>Registration</th><th>Student</th><?php foreach($sessions as $s):?><th><?=e(date('d/m/y',strtotime($s['attendance_date'])))?><br><small><?=e($s['subject_code'])?> <?=str_pad((string)$s['lecture_number'],2,'0',STR_PAD_LEFT)?></small></th><?php endforeach?><th>Present</th><th>Medical</th><th>Absent</th><th>Percentage</th></tr><?php foreach($students as $st):$present=0;$medical=0;$absent=0;?><tr><td class="registration-cell" aria-label="Registration number <?=e($st['registration_number'])?>"><span class="registration-full"><?=e($st['registration_number'])?></span><span class="registration-short" aria-label="Registration number ending <?=e(substr((string)$st['registration_number'],-4))?>"><?=e(substr((string)$st['registration_number'],-4))?></span></td><td class="student-name-cell"><?=e($st['student_name']?:'Name not entered')?></td><?php foreach($sessions as $s):$mark=$records[$st['id']][$s['id']]??'';if($mark==='present')$present++;elseif($mark==='medical')$medical++;elseif($mark==='absent')$absent++;?><td class="status-<?=e($mark)?>"><?= $mark==='present'?'P':($mark==='medical'?'M':($mark==='absent'?'A':'—')) ?></td><?php endforeach?><?php $total=$present+$medical+$absent;$percentage=$total?number_format(100*($present+$medical)/$total,1):'0.0';?><td><?=$present?></td><td><?=$medical?></td><td><?=$absent?></td><td class="attendance-percentage"><span><?=$percentage?>%</span></td></tr><?php endforeach?></table></div><?php endif?></section><?php endif;require __DIR__.'/../includes/footer.php';?>
